// Builds the Detractless bundles that Atlas ships, from payload/detractless/src.
//
//   npm run build                 -> writes payload/detractless/src/dist/*
//   node scripts/build.mjs --out <dir>   -> writes to <dir> (tests use this)
//
// Everything in src/dist is generated by this script. Never edit it by hand:
// tests/unit/build_sync.test.js fails when dist and src disagree.
import * as esbuild from "esbuild";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const PAGE_ROOT = path.join(ROOT, "payload", "detractless");
export const DIST = path.join(PAGE_ROOT, "src", "dist");

export const ENTRIES = {
  "newtab.bundle": "src/pages/newtab/newtab.js",
  "gate.bundle": "src/pages/gate/gate.js",
  "serviceWorker.bundle": "src/background/serviceWorker.js",
};

const BANNER = "/* GENERATED by scripts/build.mjs from payload/detractless/src. Do not edit; run npm run build. */";

/** Build every bundle into outDir. Returns the list of files written. */
export async function build(outDir = DIST) {
  const result = await esbuild.build({
    entryPoints: Object.fromEntries(
      Object.entries(ENTRIES).map(([name, rel]) => [name, path.join(PAGE_ROOT, rel)])
    ),
    absWorkingDir: PAGE_ROOT,
    bundle: true,
    format: "iife",
    write: false,
    outdir: outDir,
    logLevel: "warning",
    banner: { js: BANNER, css: BANNER },
    alias: { fflate: path.join(PAGE_ROOT, "vendor", "fflate", "browser.js") },
  });
  fs.mkdirSync(outDir, { recursive: true });
  const written = [];
  for (const file of result.outputFiles) {
    // The repo keeps CRLF line endings everywhere, generated files included.
    const text = file.text.replace(/\r\n/g, "\n").replace(/\n/g, "\r\n");
    fs.writeFileSync(file.path, text);
    written.push(file.path);
  }
  return written;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const i = process.argv.indexOf("--out");
  const out = i > 0 ? path.resolve(process.argv[i + 1]) : DIST;
  const files = await build(out);
  for (const f of files) console.log("built", path.relative(ROOT, f));
}
